// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 putValue, uint256 collectAm, uint256 unlockTime, address collector) public {
        vm.assume(putValue <= VALUE_CAP);
        putValue = bound(putValue, 1 ether, 100 ether);
        collectAm = bound(collectAm, 1 wei, putValue);
        unlockTime = bound(unlockTime, 0, block.timestamp);

        vm.assume(collector != address(0));
        vm.assume(collector.code.length == 0);
        vm.assume(collector != address(c));

        ReentrantCollector rc = new ReentrantCollector(address(c), collectAm);

        vm.deal(address(rc), putValue);
        rc.deposit{value: putValue}(unlockTime);

        vm.warp(block.timestamp + 1);

        uint256 contractBalanceBefore = address(c).balance;
        uint256 collectorBalanceBefore = address(rc).balance;

        rc.attack(collectAm);

        uint256 contractBalanceAfter = address(c).balance;
        uint256 collectorBalanceAfter = address(rc).balance;

        (, uint256 recordedBalance) = c.Acc(address(rc));

        uint256 etherSent = (contractBalanceBefore - contractBalanceAfter) + (collectorBalanceAfter - collectorBalanceBefore);

        assertTrue(etherSent <= recordedBalance || recordedBalance == 0, "reentrant Collect must not send more Ether than the collector's recorded balance debited by");
    }
}

contract ReentrantCollector {
    MY_BANK public target;
    uint256 public attackAm;
    bool private entered;

    constructor(address _target, uint256 _am) {
        target = MY_BANK(payable(_target));
        attackAm = _am;
    }

    function deposit(uint256 _unlockTime) external payable {
        target.Put{value: msg.value}(_unlockTime);
    }

    function attack(uint256 _am) external {
        target.Collect(_am);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            target.Collect(attackAm);
        }
    }
}
